class AuditStore:
    def __init__(self) -> None:
        self._events: list[dict] = []
        self._event_ids: set[int] = set()

    def append(self, event: dict) -> None:
        copied = dict(event)
        self._events.append(copied)
        evt_id = copied.get("evt_id")
        if isinstance(evt_id, int):
            self._event_ids.add(evt_id)

    def events(self) -> list[dict]:
        return [dict(event) for event in self._events]

    def __len__(self) -> int:
        return len(self._events)

    def _has_event_id(self, evt_id: int) -> bool:
        return evt_id in self._event_ids


def migrate_event(row: dict) -> dict:
    timestamp = row["EVT_TS"]
    return {
        "evt_id": int(row["EVT_ID"]),
        "ts": (
            f"{timestamp[0:4]}-{timestamp[4:6]}-{timestamp[6:8]}"
            f"T{timestamp[8:10]}:{timestamp[10:12]}:{timestamp[12:14]}"
        ),
        "code": row["EVT_CD"],
        "user_id": row["USR_ID"],
        "entity": row["ENT_NAME"],
        "entity_id": row["ENT_ID"],
        "old_val": row["OLD_VAL"],
        "new_val": row["NEW_VAL"],
    }


def migrate(rows: list[dict], store: AuditStore | None = None) -> AuditStore:
    target = AuditStore() if store is None else store

    for row in sorted(rows, key=lambda item: int(item["EVT_ID"])):
        event_id = int(row["EVT_ID"])
        if not target._has_event_id(event_id):
            target.append(migrate_event(row))

    return target
